<template>
  <AuthLayout :loading="false" :showInfoPanel="false">
    <AuthCard :title="$t('verify')">
      <div class="flex flex-col gap-3 text-sm text-muted-foreground">
        <p>
          {{ $t('sent_email') }}
          <span class="font-semibold text-foreground">{{ email }}</span>
          <span v-if="email_not_found" class="text-destructive font-medium ml-1">
            {{ email_not_found }}
          </span>
        </p>
        <p>{{ $t('need_to_verify') }}</p>
        <p>{{ $t('no_email') }}</p>
        <p>{{ $t('click_btn') }}</p>
      </div>

      <template #actions>
        <q-btn
          unelevated
          color="primary"
          text-color="white"
          :label="$t('sign_in')"
          class="auth-submit-btn"
          @click="goLogin()"
        />
        <div class="mt-3 flex justify-center">
          <ResendVerifyEmail :email="email" />
        </div>
      </template>
    </AuthCard>
  </AuthLayout>
</template>

<script lang="ts">
import { LocalStorage } from 'quasar';
import { defineComponent, ref } from 'vue';
import ResendVerifyEmail from 'src/pages/User/ResendVerifyEmail.vue';
import { AuthLayout, AuthCard } from 'src/components/Auth';

export default defineComponent({
  components: {
    ResendVerifyEmail,
    AuthLayout,
    AuthCard,
  },
  setup() {
    return {
      email: ref(''),
      email_not_found: ref(''),
    };
  },
  mounted() {
    this.setVerifyEmail();
  },
  methods: {
    setVerifyEmail() {
      let verify_email = LocalStorage.getItem('verify_email') as string;
      if (!LocalStorage.has('verify_email') || verify_email === null || verify_email === '') {
        this.email_not_found = this.$t('no_email_found');
        return;
      }
      this.email = verify_email;
      this.email_not_found = '';
    },
    goLogin() {
      this.$router.push('/');
    },
  },
  beforeRouteLeave(_to: any, _from: any, next: any) {
    LocalStorage.remove('verify_email');
    next();
  },
});
</script>

<style scoped lang="scss">
.auth-submit-btn {
  width: 100%;
  height: 44px;
  font-weight: 500;
  border-radius: 0.5rem;
}
</style>
